[[[
// A running HA client may have loaded its resource list before the Showcase was registered.
if (!customElements.get("u1-fusion-showcase-hero-v17") ||
    !customElements.get("u1-fusion-showcase-ironoxx")) {
  this._u1ShowcaseModule ??= import("/local/media/snapmaker-u1/showcase/u1-fusion-showcase.u1.js?v=559-17").catch(error => {
    console.error("U1 Fusion Showcase resource failed to load", error);
  });
}
const d = variables.d;
  const tone = {neutral:'#a3a7ad',hot:'#ff6347',warn:'#f3be73',error:'#ff8377',ok:'#93cc9f'}[d.tone];
  const tool = !d.known ? '' : d.active !== null ? `T${d.active} mounted` :
    d.heads.every(head => head.state === 'parked') ? '4 tools docked' : 'Tool position unknown';
  return `<style>
    .u1-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px 24px;border-bottom:1px solid var(--divider-color);padding:5px 0 16px}
    .u1-title{display:flex;align-items:center;gap:9px;color:#ff6347;font-size:clamp(27px,3.1vw,40px);font-weight:760;line-height:1.12;letter-spacing:-.035em}
    .u1-kicker{margin:0 0 4px 2px;text-transform:uppercase;letter-spacing:.14em;font-size:11px;font-weight:650;color:var(--secondary-text-color)}
    .u1-meta{display:flex;align-items:center;gap:8px 14px;flex-wrap:wrap;color:var(--secondary-text-color);font-size:13px}
    .u1-live{display:inline-flex;align-items:center;gap:8px;padding:7px 11px;border:1px solid color-mix(in srgb,var(--u1-tone),transparent 64%);border-radius:99px;color:var(--primary-text-color);font-weight:650}
    .u1-live i{width:7px;height:7px;border-radius:50%;background:var(--u1-tone);box-shadow:0 0 0 3px color-mix(in srgb,var(--u1-tone),transparent 83%)}
    @media(max-width:540px){.u1-head{gap:12px;padding-bottom:12px}.u1-meta{font-size:12px}.u1-live{padding:5px 8px}}
    </style><div class="u1-head"><div><div class="u1-kicker">Johnny5 Â· Snapmaker U1</div><div class="u1-title"><ha-icon icon="mdi:printer-3d-nozzle" style="--mdc-icon-size:1em"></ha-icon>U1 Fusion Showcase</div></div><div class="u1-meta"><span class="u1-live" style="--u1-tone:${tone}" role="status"><i aria-hidden="true"></i>${d.label}</span>${tool ? `<span>${tool}</span>` : ''}</div></div>`;
]]]

